/**
 * Revealation — generated deployment identity
 * ============================================
 *
 * Purpose
 * -------
 * Provide the running application with the build id generated by the static
 * deployment script. Development copies keep a null id; packaged copies have
 * the marker replaced with the content-derived build id.
 *
 * Responsibilities
 * ----------------
 * - expose the active deployment build id on `window.Revealation`;
 * - keep local development distinguishable from a packaged deployment.
 *
 * Does NOT
 * --------
 * - fetch deployment metadata;
 * - decide whether an update should be activated.
 *
 * Public API
 * ----------
 * `window.Revealation.build` — the generated build id, or `null` locally.
 */
(function configureBuild(global) {
  'use strict';

  const app = global.Revealation;
  if (!app) return;
  const generatedBuild = '__BUILD_ID__';
  app.build = generatedBuild.startsWith('__BUILD_') ? null : generatedBuild;
})(window);
